llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Fentanyl, the direct parent scaffold of the query, has an absolute oral bioavailability of 35% in healthy volunteers after oral administration, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C55"],
      "claim": "Alfentanil, which shares the 4-methoxymethylpiperidine and N-phenylpropanamide core with the query, has baseline oral bioavailability of 37% in healthy volunteers, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Pethidine/meperidine, a 4-arylpiperidine opioid, has absolute oral bioavailability of 0.61 in healthy volunteers, supporting high oral F for this structural family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Fenspiride, a piperidine-containing drug, shows 90% absolute bioavailability in healthy volunteers, indicating that piperidine-based drugs can be very well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Nortilidine, an aminophenyl ester opioid, has 99% systemic availability in healthy volunteers, supporting high oral bioavailability in this opioid class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Temocaprilat, a piperidine-containing drug, has about 65% absolute bioavailability, providing additional support for high F in piperidine-containing structures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Bilastine, a piperidine-containing drug, has 61% absolute oral bioavailability in healthy adults, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Ketobemidone, a 4-phenylpiperidine opioid, has mean oral bioavailability of 34% (range 17-62%), with the mean above the 20% threshold; its lower transfer score limits weight but direction remains supportive.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a fentanyl/alfentanil hybrid. Direct fentanyl and alfentanil oral bioavailability data (30-50% and 37-51%) plus multiple piperidine/opioid analogues with F values of 34-99% all support F >= 20%. The physicochemical prior is mixed, but the strong, transferable experimental evidence from close structural analogues outweighs it.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement exists for the exact query molecule.",
    "The thiophene-containing side chain may alter metabolism or transport compared with the phenethyl or tetrazolylethyl analogues.",
    "High logP and low intrinsic solubility could reduce absorption in some conditions, but ionization and analogue data mitigate this concern."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

